import {actionTypesToEvents, registerCardComponent} from "@pihanga2/core";
import {SheetCardComponent} from "./sheetCard.component";
import {PI_SHEET_ACTION, PI_SHEET_CARD} from "./sheetCard.types";

export * from "./sheetCard.types";

registerCardComponent({
  name: PI_SHEET_CARD,
  component: SheetCardComponent,
  events: actionTypesToEvents(PI_SHEET_ACTION),
});

import React from "react";
import {Card, type PiCardProps} from "@pihanga2/core";
import {cn} from "@/lib/utils";
import {
  Sheet as SheetRoot,
  SheetTrigger,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
  SheetClose,
} from "@/components/ui/sheet";
import {Button} from "@/components/ui/button";

import type {PiSheetEvents, PiSheetProps} from "./sheetCard.types";

export const SheetCardComponent = (
  props: PiCardProps<PiSheetProps, PiSheetEvents>,
): React.ReactNode => {
  const {
    id,
    trigger,
    content,
    title,
    description,
    open: controlledOpen,
    side = "right",
    footer,
    footerCloseButtonText,
    className,
    headerClassName,
    contentClassName,
    footerClassName,
    cardName,
    onOpened,
    onClosed,
    onOpenChanged,
  } = props;

  const effectiveCloseText =
    footerCloseButtonText === undefined ? "Close" : footerCloseButtonText;

  const [internalOpen, setInternalOpen] = React.useState(false);
  const open = controlledOpen ?? internalOpen;
  const prevControlledOpenRef = React.useRef(controlledOpen);

  // Detect programmatic close (controlled open: true → false)
  React.useEffect(() => {
    if (
      prevControlledOpenRef.current === true &&
      controlledOpen === false &&
      open === false
    ) {
      onClosed({id, reason: "programmatic"});
    }
    prevControlledOpenRef.current = controlledOpen;
  }, [controlledOpen, open, id, onClosed]);

  const handleOpenChange = (nextOpen: boolean) => {
    if (controlledOpen === undefined) {
      setInternalOpen(nextOpen);
    }
    onOpenChanged({open: nextOpen, id});
    if (nextOpen) {
      onOpened({id});
    } else if (controlledOpen === undefined) {
      onClosed({id, reason: "user"});
    }
  };

  function renderHeader() {
    if (!title && !description) return null;
    return (
      <SheetHeader className={headerClassName}>
        {title && <SheetTitle>{title}</SheetTitle>}
        {description && <SheetDescription>{description}</SheetDescription>}
      </SheetHeader>
    );
  }

  function renderFooter() {
    if (footer) {
      return (
        <SheetFooter className={footerClassName}>
          <Card cardName={footer} parentCard={cardName} />
        </SheetFooter>
      );
    }
    if (effectiveCloseText !== null) {
      return (
        <SheetFooter className={footerClassName}>
          <SheetClose asChild>
            <Button variant="outline">{effectiveCloseText}</Button>
          </SheetClose>
        </SheetFooter>
      );
    }
    return null;
  }

  return (
    <SheetRoot open={open} onOpenChange={handleOpenChange}>
      {trigger && (
        <SheetTrigger asChild>
          <span className="inline-flex" data-pihanga-trigger-wrapper>
            <Card cardName={trigger} parentCard={cardName} />
          </span>
        </SheetTrigger>
      )}
      <SheetContent
        data-pihanga={cardName}
        side={side}
        className={className}
      >
        {renderHeader()}
        <div className={cn("flex-1 overflow-y-auto p-4", contentClassName)}>
          <Card cardName={content} parentCard={cardName} />
        </div>
        {renderFooter()}
      </SheetContent>
    </SheetRoot>
  );
};

import {
  createCardDeclaration,
  createOnAction,
  type PiCardRef,
  registerActions,
} from "@pihanga2/core";

export const PI_SHEET_CARD = "pi/sheet";

export const Sheet = createCardDeclaration<PiSheetProps, PiSheetEvents>(
  PI_SHEET_CARD,
);

export const PI_SHEET_ACTION = registerActions(PI_SHEET_CARD, [
  "opened",
  "closed",
  "open_changed",
]);

export const onSheetOpened = createOnAction<SheetOpenedEvent>(
  PI_SHEET_ACTION.OPENED,
);

export const onSheetClosed = createOnAction<SheetClosedEvent>(
  PI_SHEET_ACTION.CLOSED,
);

export const onSheetOpenChanged = createOnAction<SheetOpenChangedEvent>(
  PI_SHEET_ACTION.OPEN_CHANGED,
);

export type PiSheetProps = {
  /**
   * Optional id passed through to events for identification.
   */
  id?: string;

  /**
   * Optional trigger card (e.g. a Button).
   *
   * When provided, clicking it opens the sheet.
   * When omitted, control the sheet via the `open` prop.
   */
  trigger?: PiCardRef;

  /**
   * Card to render as the sheet body content.
   */
  content: PiCardRef;

  /**
   * Optional sheet title (rendered in header).
   */
  title?: string;

  /**
   * Optional sheet description (rendered below title).
   */
  description?: string;

  /**
   * Controlled open state.
   * When provided, visibility is fully managed externally.
   */
  open?: boolean;

  /**
   * Which edge the sheet slides in from.
   * @default "right"
   */
  side?: "top" | "right" | "bottom" | "left";

  /**
   * Optional footer card.
   * When provided, takes precedence over the default close button.
   */
  footer?: PiCardRef;

  /**
   * Text for the default close button in the footer.
   * Set to `null` to hide the default close button.
   * @default "Close"
   */
  footerCloseButtonText?: string | null;

  /**
   * Additional CSS classes for the sheet content panel.
   */
  className?: string;

  /**
   * Additional CSS classes for the sheet header.
   */
  headerClassName?: string;

  /**
   * Additional CSS classes for the sheet body (wraps `content`).
   */
  contentClassName?: string;

  /**
   * Additional CSS classes for the sheet footer.
   */
  footerClassName?: string;
};

export type SheetOpenedEvent = {
  id?: string;
};

export type SheetClosedEvent = {
  id?: string;
  /**
   * - 'user': dismissed by user (outside click, ESC, X button)
   * - 'programmatic': closed via props.open change
   */
  reason?: "user" | "programmatic";
};

export type SheetOpenChangedEvent = {
  open: boolean;
  id?: string;
};

export type PiSheetEvents = {
  onOpened: SheetOpenedEvent;
  onClosed: SheetClosedEvent;
  onOpenChanged: SheetOpenChangedEvent;
};
